const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Point([-89.5890, 40.6936]).buffer(20000); // 20km buffer around Peoria, IL
  const startDateSep = '2022-09-01';
  const endDateSep = '2022-09-30';
  const startDateOct = '2022-10-01';
  const endDateOct = '2022-10-31';

  // Function to mask clouds using the SCL band of Sentinel-2
  function maskS2sr(image) {
    const scl = image.select('SCL');
    // Keep vegetation (4), bare soil (5), and unclassified (7)
    const mask = scl.eq(4).or(scl.eq(5)).or(scl.eq(7));
    return image.updateMask(mask);
  }

  // Function to calculate NDVI
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // 2. Data Acquisition & Processing for each period
  async function getMonthlyNDVI(startDate, endDate) {
    let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(aoi)
      .filterDate(startDate, endDate)
      .map(maskS2sr)
      .map(addNDVI);

    const imageCount = collection.size().getInfo();
    if (imageCount === 0) {
      return { ndvi: null, count: 0, imageCount: 0 };
    }

    const composite = collection.select('NDVI').median();
    const stats = composite.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: aoi,
      scale: 1000,
      maxPixels: 1e9
    });

    const ndvi = stats.get('NDVI').getInfo();
    const count = stats.get('NDVI_count').getInfo();
    return { ndvi, count, imageCount };
  }

  // 3. Calculation for September and October
  const sepData = await getMonthlyNDVI(startDateSep, endDateSep);
  const octData = await getMonthlyNDVI(startDateOct, endDateOct);

  // 4. Validation & Final Answer
  console.log(`September 2022 Images: ${sepData.imageCount}`);
  console.log(`October 2022 Images: ${octData.imageCount}`);

  if (sepData.imageCount === 0 || octData.imageCount === 0) {
    console.log("Evidence: No images found for one or both months.");
    console.log("A");
    return;
  }

  console.log(`September 2022 Valid Pixels: ${sepData.count}`);
  console.log(`October 2022 Valid Pixels: ${octData.count}`);

  if (sepData.count === 0 || octData.count === 0) {
    console.log("Evidence: No valid (non-cloudy) pixels after masking for one or both months.");
    console.log("C2");
    return;
  }

  console.log(`September 2022 Mean NDVI: ${sepData.ndvi ? sepData.ndvi.toFixed(4) : 'N/A'}`);
  console.log(`October 2022 Mean NDVI: ${octData.ndvi ? octData.ndvi.toFixed(4) : 'N/A'}`);

  if (sepData.ndvi === null || octData.ndvi === null) {
    console.log("Evidence: Failed to calculate mean NDVI.");
    console.log("C3");
    return;
  }

  // "More brown fields" means lower vegetation index (NDVI).
  if (octData.ndvi < sepData.ndvi) {
    console.log("Evidence: Mean NDVI in October was lower than in September, indicating less green vegetation.");
    console.log("A");
  } else {
    console.log("Evidence: Mean NDVI in October was not lower than in September.");
    console.log("B");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`An error occurred: ${e}`);
    console.log("D");
  }
}

initEE();
